attempts.script:
# Create the output directory if it doesn't exist
file mkdir outputs

# Open the output file
set output_file [open "outputs/unloaded_nets.txt" "w"]

# Get all nets in the design
set all_nets [get_nets *]

foreach net $all_nets {
    # Skip internal power/ground nets if any, though typically they have no drivers
    # We focus on signal nets. get_pins will return pins connected to this net.

    # Get all pins connected to this net
    set pins [get_pins -of_objects $net]

    set has_driver 0
    set driver_info ""
    set has_load 0

    foreach pin $pins {
        # Determine the type and direction of the pin
        set pin_type [sta::object_type $pin]

        if { $pin_type == "Pin" } {
            # It's an instance pin
            set direction [sta::pin_direction $pin]

            if { $direction == "output" } {
                set has_driver 1
                if { $driver_info == "" } {
                    # Get the instance name and pin name for the output
                    set inst [sta::pin_instance $pin]
                    set inst_name [get_full_name $inst]
                    set pin_name [sta::pin_name $pin]
                    set driver_info "$inst_name/$pin_name"
                }
            } elseif { $direction == "input" || $direction == "inout" } {
                # Instance input or inout pins are considered loads
                set has_load 1
            }
        } elseif { $pin_type == "Port" } {
            # It's a top-level port
            set direction [sta::port_direction $pin]

            # If the port is an output port, it is a load for the net driving it
            # If the port is an input port, it is a driver for the net
            if { $direction == "output" } {
                set has_load 1
            } elseif { $direction == "input" || $direction == "inout" } {
                set has_driver 1
                if { $driver_info == "" } {
                    # For ports, the "driver instance" is effectively the port itself.
                    # The format requested is <net_name> <driver_instance>/<driver_pin>.
                    # For a top-level input port, we can use the port name as both instance and pin,
                    # or just the port name. Let's use the port name as the identifier.
                    set port_name [get_full_name $pin]
                    set driver_info "$port_name/$port_name"
                }
            }
        }
    }

    # Check if the net has a driver but no load
    if { $has_driver && !$has_load } {
        puts $output_file "[get_full_name $net] $driver_info"
    }
}

close $output_file
